import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { WalletModel } from 'src/app/_models';
import { WalletService } from 'src/app/_services';

@Component({
    selector: 'app-wallet-create',
	host: { 'class': 'childRouteFlex' },
    templateUrl: './wallet-create.component.html',
    styleUrls: ['./wallet-create.component.css']
})
export class WalletCreateComponent {
    constructor(public walletService: WalletService, private router: Router) {}

    addWallet() {
        this.walletService.addWallet().subscribe((wallet: WalletModel) => {
            console.log(wallet);
            this.router.navigate(['/wallet']);
        });
    }
}
<div class="component-header">
    <div>
        <i
            class="bi bi-arrow-left-circle pointer"
            appGoPageBack
            style="cursor: pointer"
        ></i>
        &nbsp;&nbsp;
        <span>New Wallet</span>
    </div>
</div>

<br />

<div class="childMainPage">
    <div>
        <input
            class="default-input primary"
            type="text"
            [(ngModel)]="this.walletService.newWallet.name"
            placeholder="Wallet Name"
        />
    </div>
    <div>
        <input
            class="default-input primary"
            type="text"
            [(ngModel)]="this.walletService.newWallet.currencyCode"
            placeholder="Wallet Currency Code"
        />
    </div>
</div>

<div class="bottom-button">
    <button class="default-button" (click)="addWallet()">Create Wallet</button>
</div>
